INSERT INTO indicadors (codi, capacitat_id, capacitat, requisit, text, color_cap, color_ind) VALUES
  ('c1.1', 'c1', 'Organització del treball', 'Lliura les tasques/ Treball diari', 'Compleix amb els requisits i terminis d''entrega', '#B4A7D6', '#D9D2E9'),
  ('c1.2', 'c1', 'Organització del treball', 'Endreça i estructura dels treballs (maquetació)', 'Estructura els documents entregats seguint la línia estipulada pel centre/departament', '#B4A7D6', '#D9D2E9'),
  ('c1.3', 'c1', 'Organització del treball', 'Planifica les activitats per la realització dels projectes / treballs', 'Realitza el seguiment de la planificació i temporalització realitzada i fa les modificacions necessàries.', '#B4A7D6', '#D9D2E9'),
  ('c2.1', 'c2', 'Iniciativa', 'Aporta idees noves (innovació)', 'Aplicar les fases d''un procés d''innovació obtenint un bon resultat.', '#FFE599', '#FFF2CC'),
  ('c2.2', 'c2', 'Iniciativa', 'Domini dels diferents recursos (creativitat)', 'Aportar idees.', '#FFE599', '#FFF2CC'),
  ('c2.3', 'c2', 'Iniciativa', 'Actitud proactiva', 'Davant d''una situació difícil en la que cal prendre una decisió, busques ajuda, aportes idees.', '#FFE599', '#FFF2CC'),
  ('c2.4', 'c2', 'Iniciativa', 'Capacitat de lideratge', 'Té en compte les possibles conseqüències de les decisions que ha de prendre. Triant l''estil de lideratge que més s''adapti al grup amb el que treballa, permeten als companys, membres de l''equip o participants que donin la seva opinió.', '#FFE599', '#FFF2CC'),
  ('c3.1', 'c3', 'Responsabilitat en el treball', 'Assistència i puntualitat', 'Compleix amb l''horari i assistència marcada , participant en les activitats clau com: simulacres, impactes, càpsules formatives I justifica les faltes d''assistència al tutor i al docent del mòdul.', '#A4C2F4', '#C9DAF8'),
  ('c3.2', 'c3', 'Responsabilitat en el treball', 'S''implica activament en la realització de les tasques', 'Mostra iniciativa i interés a l''hora de realitzar les tasques, responsabilitzat-se de la seva part i ajudant als companys.', '#A4C2F4', '#C9DAF8'),
  ('c3.3', 'c3', 'Responsabilitat en el treball', 'Té cura del material i dels companys', 'Respecta el material tant propi com extern/ordre a la classe/recollir (ordinadors, taules,cadires, material esportiu)', '#A4C2F4', '#C9DAF8'),
  ('c3.4', 'c3', 'Responsabilitat en el treball', 'Compleix la normativa de centre i de les entitats amb les quals es col·labora', 'Compleix la normativa del centre i de les diferents instal·lacions on participa com alumne de l''IEB.', '#A4C2F4', '#C9DAF8'),
  ('c3.5', 'c3', 'Responsabilitat en el treball', 'Té una imatge professional envers el treball', 'Porta el material i equipació necessària per la realització de les activitats.', '#A4C2F4', '#C9DAF8'),
  ('c4.1', 'c4', 'Autonomia', 'Perseverança', 'Demostra la utilització de diferents mètodes per sobreposar-se a les dificultats per aconseguir els objectius amb qualitat.', '#B6D7A8', '#D9EAD3'),
  ('c4.2', 'c4', 'Autonomia', 'Capacitat d''adaptació', 'Desenvolupa les seves tasques sense l''ajuda de ningú', '#B6D7A8', '#D9EAD3'),
  ('c4.3', 'c4', 'Autonomia', 'Capacitat crítica', 'Realitza autoavaluacions exigents, identificant objectivament les fortaleses i els aspectes de millora.', '#B6D7A8', '#D9EAD3'),
  ('c4.4', 'c4', 'Autonomia', 'Manté una actitud professional (saber estar)', 'Té un saber estar a classe (mòbil, interrupcions, auriculars, menjar...).', '#B6D7A8', '#D9EAD3'),
  ('c5.1', 'c5', 'Treball en equip', 'Accepta el rol dintre de l''equip', 'Aplica les funcions del rol que accepta i li ha tocat portar a terme, sense dificultar el repartiment dels rols dels companys', '#A2C4C9', '#D0E0E3'),
  ('c5.2', 'c5', 'Treball en equip', 'Dona suport als companys', 'Ajuda als companys quan ho necessiten, motiva i anima a participar i pendre decisions.', '#A2C4C9', '#D0E0E3'),
  ('c5.3', 'c5', 'Treball en equip', 'Coavalua de forma objectiva als companys', 'Sap aplicar la rúbrica de forma objectiva.', '#A2C4C9', '#D0E0E3'),
  ('c5.4', 'c5', 'Treball en equip', 'Prioritza el fi comú versus l''individual', 'Organitza bé el temps per arribar a tot i assolir els objectius grupals.', '#A2C4C9', '#D0E0E3'),
  ('c5.5', 'c5', 'Treball en equip', 'Actua com a mediador en cas necessari', 'Sap agafar el rol de mediador en cas d''un conflicte.', '#A2C4C9', '#D0E0E3'),
  ('c6.1', 'c6', 'Relacions interpersonals', 'Escolta activa', 'Mira a l''altre persona quan t''està parlant i quan no entens el que estan explicant no dubtes en preguntar.', '#F9CB9C', '#FCE5CD'),
  ('c6.2', 'c6', 'Relacions interpersonals', 'Capacitat de posar-se en el lloc dels altres (empatia)', 'Sap posar-se al lloc de l''altre per entendre com se sent l''altre part.', '#F9CB9C', '#FCE5CD'),
  ('c6.3', 'c6', 'Relacions interpersonals', 'Capacitat assertiva per exigir compromís als companys/es', 'Escolta i deixa parlar encara que no estigui d''acord amb el que està sentint.', '#F9CB9C', '#FCE5CD'),
  ('c6.4', 'c6', 'Relacions interpersonals', 'Adequació del llenguatge', 'Utilitza formes correctes de comunicació que s''adapten a cada col·lectiu i entorn de pràctica/treball.', '#F9CB9C', '#FCE5CD'),
  ('c6.5', 'c6', 'Relacions interpersonals', 'Tolerància versus les opinions dels altres', 'Quan jutja la opinió dels altres ho fa amb respecte i compartint el "perquè" d''aquest judici.', '#F9CB9C', '#FCE5CD'),
  ('c7.1', 'c7', 'Resolució de problemes', 'Identifica les mancances o necessitats pròpies/equip de treball/projectes', 'Raona en ordre lògic un procés de resolució i posa en pràctica fórmules de resolució efectives.', '#EA9999', '#F4CCCC'),
  ('c7.2', 'c7', 'Resolució de problemes', 'És capaç de nodrir-se de diferents fonts per resoldre els problemes', 'És capac de discriminar la informació fiable i fer-ne un ús correcte.', '#EA9999', '#F4CCCC'),
  ('c7.3', 'c7', 'Resolució de problemes', 'Resolució i seguiment  de problema', 'Afronta i/o resol els problemes amb eficàcia i eficiència seguint els acords presos.', '#EA9999', '#F4CCCC');
